/**
 * A Warning
 * ----------
 * Enoch prophesies: the Lord comes with ten thousands of his holy ones to judge all. Stage: a crowded market square at midday, a lone voice rising, the crowd turning; the sky darkening at the edges; a still point of dread.
 *
 * Palette 0x241810 → 0x060402 · light: dusk · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./enoch-kit.js.
 */

import { THREE, createScene, pillar, person, crowd } from './enoch-kit.js';

const BG = 0x241810;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 2466304182, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x060402 });
    W.disc([0, 6, -12], 5, 0x2f1f15, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x291c12, wrapTrim: 0x19110b, beard: 'long', ry: 0.60, s: 1.17 });
    person(W, group, [4.5, 0, 6], { robe: 0x8a6a44, head: 'wrap', wrap: 0x291c12, wrapTrim: 0x19110b, beard: 'long', ry: -0.62, s: 1.13 });
    person(W, group, [1, 0, -5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x291c12, wrapTrim: 0x19110b, beard: 'long', ry: 0.46, s: 1.06 });
    /* crowd: the people of the story */
    crowd(W, group, 0, 16, 19, 70, 44, [0x241810, 0x060402, 0x8a6a44, 0x6a4a30, 0xc8b088, 0x5a4a6a]);

    return W.finish();
}

export default { build };
